modelmap={p['reference_id']:p for p in manifest['parts']}
shutil.copytree(MODELS/'previews',OUT/'goblin-previews',dirs_exist_ok=True)
e=html.escape;cards=[]
for p in doc['parts']:
 m=MODELS/p['goblin_file'];preview=MODELS/'previews'/(m.stem+'.png');info=modelmap.get(p['id'],{});ready=m.exists() and bool(info)
 p.update(model_status='exported' if ready else 'not-built',model_path=str(m) if ready else None,exported_animations=info.get('animations',[]),preview_path=str(preview) if preview.exists() else None)
 ref=f'<img src="{e(p["reference_image"])}" loading="lazy">' if p['reference_image'] else '<span>No numbered icon</span>'
 art=f'<img src="goblin-previews/{preview.name}" loading="lazy">' if preview.exists() else '<span>Render pending</span>'
 bounds=info.get('bounds_blender_z_up',[[0,0,0],[0,0,0]]);dimensions=' × '.join(f'{bounds[1][k]-bounds[0][k]:.2f}' for k in range(3))
 controls='\n'.join(c['declaration'] for c in p['code_controls']);classes=', '.join(c['class'] for c in p['source_classes']);clips=', '.join(c['name'] for c in info.get('animations',[])) or 'Static'
 search=' '.join([p['name'],p['symbol'],p['category'],p['function'],classes]).lower()
 cards.append(f'''<article data-category="{e(p['category'])}" data-search="{e(search)}" data-visibility="{e(p['visibility'])}"><small>#{p['id']:03d} / {e(p['category'])}</small><h2>{e(p['name'])}</h2><code>{e(p['symbol'])}</code><div class="pictures"><figure>{ref}<figcaption>Besiege reference</figcaption></figure><figure>{art}<figcaption>Original Goblin model</figcaption></figure></div><p>{e(p['function'])}</p><p style="font-size:12px;color:#65695e">Bounds: {dimensions} m · previews fit each part</p><p class="status">{'Model exported' if ready else 'Model pending'} · gameplay not ported</p><details><summary>Controls, animation and source evidence</summary><p>Clips: {e(clips)}</p><p>Controller: {e(classes)}</p><pre>{e(controls or 'Passive behavior / serialized mechanical joint settings.')}</pre><p>Gameplay parity: {e(p['parity_status'])}.</p><p>{e(p['behavior_decode_error'] or '')}</p></details></article>''')
options=''.join(f'<option>{e(c)}</option>' for c in sorted({p['category'] for p in doc['parts']}))
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Goblin Scraper / Parts workshop</title><style>
*{box-sizing:border-box}body{margin:0;background:#eeeae0;color:#262921;font:16px/1.5 system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:32px}h1{font-size:34px;line-height:1.1}h2{font-size:21px;margin:4px 0}small,figcaption{color:#64675e}.intro{max-width:1000px}.note{border-left:4px solid #a16c1f;padding:12px 16px;background:#e4dccd}.controls{position:sticky;top:0;background:#eeeae0f5;display:flex;gap:12px;align-items:center;padding:16px 0;z-index:1;flex-wrap:wrap}input[type=search],select{font:inherit;border:1px solid #a9aa9f;background:white;padding:10px}input[type=search]{flex:1;min-width:250px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:18px}article{background:#fbfaf6;border:1px solid #cbcbbf;padding:20px;display:flex;flex-direction:column}article[hidden]{display:none}.pictures{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:16px 0}figure{margin:0;text-align:center;min-width:0}figure img{height:150px;width:100%;object-fit:contain;background:#dedfd5}figure span{display:flex;align-items:center;justify-content:center;height:150px;background:#e5e4de;color:#717268}figcaption{font-size:12px;margin-top:5px}.status{font-size:12px;color:#745019;border-top:1px solid #dfdfd5;padding-top:10px;margin-top:auto}code{font-size:12px;color:#6f7268}summary{cursor:pointer;font-size:13px;color:#3e4c35}details{font-size:13px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px;background:#eaece3;padding:12px}a{color:#435b32}footer{margin-top:32px;font-size:13px;color:#62665b}</style><main><h1>Goblin Scraper / Parts workshop</h1><div class="intro"><p>Standard blocks and conventional flight equipment. Sea propulsion, fuel and space systems are excluded. Compare its silhouette, read its purpose, and inspect the controller evidence.</p><p class="note">New models and mechanical clips are art assets. The full gameplay port is unfinished: ByteEngine needs an angular/joint solver and verified combat, flight, fluid, fuel and automation behavior. Animation is not proof of a working simulation.</p><p>80 models: 79 parts and the protected master. Existing unused and internal identifiers are excluded. Rocket's original behavior payload has a recorded decoding error; its controller is identified.</p></div><div class="controls"><input id="search" type="search" placeholder="Search parts or functions" aria-label="Search parts"><select id="category" aria-label="Category"><option value="">All categories</option>OPTIONS</select><label><input id="internal" type="checkbox"> Show internal / unused</label><span id="count"></span></div><section class="grid">CARDS</section><footer>Installed Besiege imagery is for local reference only. Goblin geometry, rigs and textures are independently authored. <a href="BESIEGE-PARTS.md">Full inventory</a> · <a href="besiege-parts-inventory.json">Decoded settings / source hashes</a><p>Online references: <a href="https://blog.ja.playstation.com/2025/01/20/20250120-besiege/">PlayStation</a> · <a href="https://steamcommunity.com/sharedfiles/filedetails/?id=2400348420">Block reference gallery</a> · <a href="https://playdigious.helpshift.com/hc/en/33-besiege/faq/608-where-is-the-build-surface-block/">Official surface-block help</a></p></footer></main><script>const cards=[...document.querySelectorAll('article')],s=document.querySelector('#search'),c=document.querySelector('#category'),i=document.querySelector('#internal');function filter(){let count=0;for(const a of cards){a.hidden=!(a.dataset.search.includes(s.value.toLowerCase())&&(!c.value||a.dataset.category===c.value)&&(i.checked||['reference-palette','protected-root'].includes(a.dataset.visibility)));if(!a.hidden)count++}document.querySelector('#count').textContent=count+' parts shown'}for(const v of [s,c,i])v.addEventListener('input',filter);filter();</script></html>'''
(OUT/'PARTS-WORKSHOP.html').write_text(page.replace('OPTIONS',options).replace('CARDS',''.join(cards)),encoding='utf-8')
(OUT/'besiege-parts-inventory.json').write_text(json.dumps(doc,indent=2),encoding='utf-8')
print('Gallery ready',len(modelmap),'exported models')
